def can_make_abc(cards):
    # Check if the cards can be rearranged to form 'abc'
    if 'abc' in cards:
        return "YES"

    # Check if we can make the cards 'abc' with at most one swap
    for i in range(len(cards)):
        for j in range(i+1, len(cards)):
            if cards[i] == cards[j] and cards[i] != 'a':
                # Swap cards[i] and cards[j]
                cards[i], cards[j] = cards[j], cards[i]
                # Check if the new array is 'abc'
                if 'abc' in cards:
                    return "YES"
                # Swap back to original array
                cards[i], cards[j] = cards[j], cards[i]

    return "NO"

