import sys

def max_product_with_one_increment(n, a):
    max_product = 0
    for i in range(n):
        if a[i] == 0:
            continue
        product = 1
        for j in range(n):
            if j != i:
                product *= a[j]
        if product > max_product:
            max_product = product
    return max_product

