def min_operations_to_remove_black_cells(n, k, s):
    black_cells = []

    # Identify all black cells
    for i in range(n):
        if s[i] == 'B':
            black_cells.append(i)

    # Calculate the minimum number of operations for each black cell
    operations = 0
    for i in black_cells:
        operations += (n - i) // k

    return operations

