def canTraverse(nums: List[int]) -> bool:
    """
    Determine if it is possible to traverse between all pairs of indices in the array nums.
    """
    n = len(nums)
    for i in range(n):
        for j in range(i + 1, n):
            if math.gcd(nums[i], nums[j]) <= 1:
                return False
    return True

