def getSortedOccupiedPositions(nums, moveFrom, moveTo):
    # Create a dictionary to store the positions of the marbles
    positions = {}
    for i in range(len(nums)):
        positions[nums[i]] = i

    # Create a list to store the final positions
    final_positions = []

    # Apply the moves
    for i in range(len(moveFrom)):
        final_positions.append(positions[moveFrom[i]])

        # Move all marbles at position moveFrom[i] to position moveTo[i]
        for j in range(len(moveFrom)):
            if j != i:
                positions[moveFrom[j]] = moveTo[j]

    # Sort the final positions
    final_positions.sort()

    return final_positions

