def maxJumps(nums, target):
    n = len(nums)
    dp = [[-1] * (target + 1) for _ in range(n)]

    def dfs(i, j):
        if dp[i][j] != -1:
            return dp[i][j]

        max_jumps = 0
        for k in range(i + 1, n):
            if nums[k] - nums[i] <= target and dp[i][k] != -1:
                max_jumps = max(max_jumps, dfs(i, k) + 1)

        dp[i][j] = max_jumps
        return dp[i][j]

    return dfs(0, n - 1)

