    return sorted(prime_pairs, key=lambda x: x[0])

def canMakeAllZero(nums, k):
    if k == 0:
        return False

    # Create a new array to store the result
    result = [0] * len(nums)

    # Iterate over the array in steps of k
    for i in range(0, len(nums), k):
        # Decrease the elements in the subarray by 1
        for j in range(i, i + k):
            result[j] -= 1

    # Check if all elements are 0
    return all(x == 0 for x in result)

