def permuteVowels(s: str) -> str:
    vowels = 'aeiou'
    consonants = 'bcdfghjklmnpqrstvwxyz'

    def swap(i, j):
        s[i], s[j] = s[j], s[i]

    def sortVowels(s):
        vowels = sorted(s, key=lambda x: ord(x) - ord('a'))
        return ''.join(vowels)

    def permute(s):
        if len(s) == 1:
            return s

        result = []
        for i in range(len(s)):
            if s[i] not in vowels:
                result.append(s[i])
            else:
                swap(i, len(s) - 1 - i)

        return ''.join(result)

    return sortVowels(permute(s))

def find_min_split(nums):
    n = len(nums)
    freq = {}
    dominant = None

    # Count the frequency of each element
    for num in nums:
        freq[num] = freq.get(num, 0) + 1

    # Find the dominant element
    for num in freq:
        if freq[num] * 2 > n:
            dominant = num
            break

    # If there is no dominant element, return -1
    if dominant is None:
        return -1

    # Find the minimum index of a valid split
    min_split_index = -1
    for i in range(n):
        if nums[i] == dominant:
            if freq[nums[i]] * 2 > n:
                min_split_index = i
                break

    return min_split_index

