def minCost(s1: str, s2: str, x: int) -> int:
    n = len(s1)

    # If the lengths of the two strings are not equal, return -1
    if n != len(s2):
        return -1

    # If the strings are already equal, return 0
    if s1 == s2:
        return 0

    # Create a dictionary to store the cost of flipping a character
    flip_cost = {0: x, 1: x}

    # Iterate over the strings
    for i in range(n):
        # Check if the current character in s1 and s2 are the same
        if s1[i] != s2[i]:
            # If they are different, we need to flip both
            if s1[i] == '0' and s2[i] == '1':
                flip_cost[1] += flip_cost[0]
            elif s1[i] == '1' and s2[i] == '0':
                flip_cost[0] += flip_cost[1]
            else:
                return -1

    # If we have flipped all characters, return the total cost
    if flip_cost[0] == 0 and flip_cost[1] == 0:
        return flip_cost[0] + flip_cost[1]

    # If we have flipped some characters, return the minimum cost
    return min(flip_cost[0], flip_cost[1])

