def maxSumOfSquares(nums, k):
    MOD = 10**9 + 7
    nums.sort()

    def get_max_and_min(nums):
        max_and = nums[0]
        min_and = nums[0]
        for num in nums[1:]:
            max_and = max(max_and, num)
            min_and = min(min_and, num)
        return max_and, min_and

    def get_sum_of_squares(max_and, min_and):
        return (max_and * max_and + min_and * min_and) % MOD

    max_and, min_and = get_max_and_min(nums)
    return get_sum_of_squares(max_and, min_and)

