def maximumXOR(a: int, b: int, n: int) -> int:
    MOD = 10**9 + 7
    max_val = 0
    for x in range(1, 2**n):
        a_xor = a ^ x
        b_xor = b ^ x
        val = (a_xor * b_xor) % MOD
        if val > max_val:
            max_val = val
    return max_val

