def canMakePalindrome(s, queries):
    n = len(s)
    for i in range(n // 2):
        a, b, c, d = queries[i]
        s[a:b+1] = s[c:d+1] = s[b:a+1] = s[d:c+1] = Counter(s[a:b+1])
        s[c:d+1] = s[b:a+1] = s[d:c+1] = Counter(s[c:d+1])
        if s != s[::-1]:
            return False
    return True

