def max_partitions(s: str, k: int) -> int:
    def count_partitions(s: str, k: int) -> int:
        count = 0
        distinct_chars = set()
        for char in s:
            if len(distinct_chars) < k:
                distinct_chars.add(char)
            else:
                distinct_chars.remove(char)
                count += 1
        return count

    if k == 1:
        return len(s)
    else:
        return count_partitions(s, k)

from collections import defaultdict

def minCost(source, target, original, changed, cost):
    n = len(source)
    cost_dict = defaultdict(list)
    for i in range(n):
        cost_dict[original[i]].append(i)

    for i in range(n):
        for j in cost_dict[original[i]]:
            if j not in cost_dict[changed[i]]:
                cost_dict[changed[i]].append(j)

    total_cost = 0
    for i in range(n):
        if i not in cost_dict[target[i]]:
            total_cost += cost[i]

    return total_cost if total_cost < n * (n - 1) // 2 else -1

