def minimumOr(nums, k):
    nums.sort()
    n = len(nums)

    for i in range(n):
        if k == 0:
            break

        # Find the smallest index j such that nums[j] & nums[i] > nums[i]
        j = i
        while j < n - 1 and nums[j] & nums[i] <= nums[i]:
            j += 1

        # Replace nums[i] and nums[j] with nums[i] & nums[j]
        nums[i], nums[j] = nums[j], nums[i]

        # Update the remaining elements
        for j in range(i + 1, n):
            if nums[j] & nums[i] == nums[i]:
                nums[j] &= nums[i]
                break

        # Update the OR of the remaining elements
        for j in range(i + 1, n):
            if nums[j] & nums[i] == nums[i]:
                nums[j] |= nums[i]
                break

    return nums[n - 1]

def largestPerimeter(nums):
    n = len(nums)
    if n < 3:
        return -1

    # Sort the array in descending order
    nums.sort(reverse=True)

    # Check if the largest possible perimeter is possible
    if nums[0] + nums[1] + nums[2] > nums[n-1]:
        return -1

    # Try to form a polygon with the largest possible perimeter
    for i in range(n-2):
        if nums[i] + nums[i+1] + nums[i+2] > nums[n-1]:
            return nums[i] + nums[i+1] + nums[i+2]

    return -1

