def longestCommonPrefix(arr1, arr2):
    # Function to find the longest common prefix between two numbers
    def common_prefix(x, y):
        x = str(x)
        y = str(y)
        min_len = min(len(x), len(y))
        for i in range(min_len):
            if x[i] != y[i]:
                return x[:i]
        return x[:min_len]

    # Initialize the maximum length of common prefix
    max_len = 0

    # Iterate over all pairs of numbers from arr1 and arr2
    for x in arr1:
        for y in arr2:
            # Find the longest common prefix between x and y
            common_prefix_len = common_prefix(x, y)
            # Update the maximum length of common prefix
            max_len = max(max_len, common_prefix_len)

    return max_len

