def insert_numbers(N, A):
    if N == 2:
        return A

    for i in range(1, N):
        if abs(A[i] - A[i-1]) == 1:
            break

        A[i], A[i-1] = A[i-1], A[i]

        if A[i] < A[i-1]:
            A[i], A[i-1] = A[i-1], A[i]
        else:
            A[i], A[i-1] = A[i-1], A[i]

    return A

