def can_win_cheating(S, T):
    # Check if the number of characters in S and T are the same
    if len(S) != len(T):
        return "No"

    # Create a dictionary to store the frequency of each character in S and T
    char_freq_S = {}
    char_freq_T = {}

    for char in S:
        char_freq_S[char] = char_freq_S.get(char, 0) + 1

    for char in T:
