def max_candies(H, W, T, grid):
    # Find the start and goal positions
    start = None
    goal = None
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'G':
                goal = (i, j)

    # If start and goal are not found, return -1
    if start is None or goal is None:
        return -1

    # Initialize the maximum number of candies visited
    max_candies = 0

    # Directions for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Breadth-first search to find the maximum number of candies
    def bfs(start_i, start_j, goal_i, goal_j, T):
        queue = [(start_i, start_j, 0, 0)]
        visited = set()
        visited.add((start_i, start_j))

        while queue:
            i, j, moves, candies = queue.pop(0)

            if moves >= T:
                continue

            if (i, j) == goal_i and candies > max_candies:
                max_candies = candies

            for di, dj in directions:
                ni, nj = i + di, j + dj
                if 0 <= ni < H and 0 <= nj < W and (ni, nj) not in visited:
                    visited.add((ni, nj))
                    queue.append((ni, nj, moves + 1, candies + 1))

    bfs(start[0], start[1], goal[0], goal[1], T)

    return max_candies

