        # Check if the new position is within the bounds and not an item
        if 0 <= new_x < 2 * 10**5 and 0 <= new_y < 2 * 10**5 and (new_x, new_y) not in x_list and (new_x, new_y) not in y_list:
            # Check if the new health is less than K
