def solve(N, S):
    S = list(S)
    i = 0
    while i < N - 1:
        if S[i] == '(' and S[i + 1] == ')':
            S[i] = ')'
            S[i + 1] = '('
            i += 2
        else:
            i += 1
    return ''.join(S)

MOD = 998244353

def count_ways(N, M):
    if N == 1:
        return M % MOD
    if N == 2:
        return (M * (M - 1)) % MOD
    if N == 3:
        return (M * (M - 1) * (M - 2)) % MOD
    if N == 4:
        return (M * (M - 1) * (M - 2) * (M - 3)) % MOD

    # For N > 3, we need to consider the circular arrangement
    # We can use dynamic programming to solve this

    # Initialize dp[i][j] as the number of ways to distribute integers to persons 1 to i
    # such that persons 1 to i have integers from 0 to j
    dp = [[0] * (M + 1) for _ in range(N + 1)]

    # Base case: for N = 1, the number of ways is M % MOD
    for j in range(M + 1):
        dp[1][j] = j % MOD

    # Fill the dp table
    for i in range(2, N + 1):
        for j in range(M + 1):
            dp[i][j] = (dp[i - 1][j] + dp[i - 1][j - 1]) % MOD

    # The answer is the number of ways to distribute integers to persons 1 to N such that persons 1 to N have integers from 0 to M-1
    return dp[N][M]

def check_path(H, W, S):
    # Check if the length of the string matches the number of cells in the grid
    if len(S) != H:
        return "No"

    # Check if the length of the string matches the number of cells in the grid
    if len(S) != W:
        return "No"

    # Initialize the visited cells
    visited = [[False]*W for _ in range(H)]

    # Starting point
    visited[0][0] = True

    # Define the movement directions
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    # Function to check if a cell is visited
    def is_visited(x, y):
        return visited[x][y]

    # Function to check if a cell is adjacent to the current cell
    def is_adjacent(x, y):
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < H and 0 <= ny < W and not visited[nx][ny] and S[nx][ny] == S[x][y]:
                return True
        return False

    # Function to check if the letter on the current cell matches the next letter in the sequence
    def is_next_letter(x, y):
        for i in range(5):
            if (x + i) % 5 == 1 and S[x + i][y] == S[x][y]:
                return True
        return False

    # Function to check if the sequence of letters is valid
    def is_valid_sequence(x, y, visited, S):
        if x == H - 1 and y == W - 1:
            return True
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < H and 0 <= ny < W and not visited[nx][ny] and S[nx][ny] == S[x][y]:
                if is_valid_sequence(nx, ny, visited, S):
                    return True
        return False

    # Check if the starting cell is visited
    if not is_visited(0, 0):
        return "No"

    # Check if the starting cell is adjacent to the starting cell
    if not is_adjacent(0, 0):
        return "No"

    # Check if the starting cell is the last cell in the sequence
    if not is_next_letter(0, 0):
