def find_cycle(N, A):
    visited = [False] * (N + 1)
    parent = [-1] * (N + 1)
    cycle = []

    def dfs(v):
        nonlocal cycle
        visited[v] = True
        parent[v] = -1
        for i in range(1, N + 1):
            if not visited[i] and A[i] == v:
                if parent[i] == -1:
                    parent[i] = v
                    cycle.append(i)
                    dfs(i)
                    cycle.pop()
                    visited[i] = False

    for i in range(1, N + 1):
        if not visited[i]:
            dfs(i)

    return len(cycle), cycle

