def min_seconds_to_stop_reels(M, S):
    # Check if it's possible to stop all reels so that all displayed characters are the same
    if M % 2 != 0:
        return -1

    # Initialize the minimum seconds to a large number
    min_seconds = float('inf')

    # Iterate over all possible values of t
    for t in range(M):
        # Check if all reels display the same character
        if all(S[i] == S[i + t] for i in range(M - t)):
            # Calculate the time to stop each reel
            seconds = t * (M // 2)
            # Update the minimum seconds
            min_seconds = min(min_seconds, seconds)

    # If no valid t was found, return -1
    if min_seconds == float('inf'):
        return -1
    else:
        return min_seconds

