def min_travel_time(N, A, B, C, D):
    # Initialize the dp array with infinity
    dp = [[float('inf')] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = D[0][0]

    # Fill the dp array
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            if i == 1 and j == N:
                dp[i][j] = 0
            elif i == 1:
                dp[i][j] = min(dp[i][j], dp[i - 1][j] + D[i - 1][j])
            elif j == 1:
                dp[i][j] = min(dp[i][j], dp[i][j - 1] + D[i][j])
            else:
                dp[i][j] = min(dp[i][j], dp[i - 1][j] + D[i - 1][j] + B + C)
                dp[i][j] = min(dp[i][j], dp[i][j - 1] + D[i][j] + C)

    return dp[N][N]

