def count_green_components(grid):
    H, W = len(grid), len(grid[0])
    visited = [[False]*W for _ in range(H)]

    def dfs(x, y):
        if x < 0 or x >= H or y < 0 or y >= W or visited[x][y] or grid[x][y] == '#':
            return 0
        visited[x][y] = True
        count = 1
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < H and 0 <= ny < W and not visited[nx][ny] and grid[nx][ny] == '#':
                count += dfs(nx, ny)
        return count

    total_components = 0
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#' and not visited[i][j]:
                total_components += 1
                visited[i][j] = True

    return total_components % MOD

