def min_tour_length(N, M, X):
    # Create a distance matrix to store the shortest path between all pairs of islands
    dist = [[float('inf')] * N for _ in range(N)]

    # Initialize the distance matrix with the given X values
    for i in range(N):
        dist[X[i] - 1][i] = X[i]

    # Floyd-Warshall algorithm to find the shortest path between all pairs of islands
    for k in range(N):
        for i in range(N):
            for j in range(N):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Find the minimum tour length by considering all possible bridges to be closed
    min_tour_length = float('inf')
    for i in range(N):
        for j in range(N):
            if dist[i][j] < float('inf'):
                min_tour_length = min(min_tour_length, dist[i][j])

    return min_tour_length

