import heapq

def f(N, M):
    graph = [[] for _ in range(N + 1)]
    for _ in range(M):
        l, d, k, c, A, B = map(int, input().split())
        for i in range(k):
            graph[A].append((B, c))
        graph[B].append((A, c))

    dist = [float('-inf')] * (N + 1)
    dist[1] = 0
    pq = [(0, 1)]

    while pq:
        current_dist, current_station = heapq.heappop(pq)

        if current_dist > dist[current_station]:
            continue

        for neighbor, weight in graph[current_station]:
            distance = current_dist + weight
            if distance < dist[neighbor]:
                dist[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return dist[N] if dist[N] != float('-inf') else -1

