    ones_picked[0] = nums[0]

    # Initialize the number of changes made
    changes = 0

    # Iterate over the array
    for i in range(1, n):
        if nums[i] == 1:
            ones_picked[i] = ones_picked[i-1] + 1
        else:
            ones_picked[i] = ones_picked[i-1]

        # Check if we can make changes
        if changes + maxChanges > k:
            return -1

        # Check if we can pick up k ones
        if ones_picked[i] == k:
