def min_max_distance(points):
    n = len(points)
    if n < 2:
        return 0

    # Calculate the maximum distance between any two points
    max_distance = 0
    for i in range(n):
        for j in range(i + 1, n):
            distance = abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1])
            max_distance = max(max_distance, distance)

    # Remove each point and calculate the new maximum distance
    for i in range(n):
        points.pop(i)
        new_max_distance = 0
        for j in range(n):
            if j != i:
                distance = abs(points[j][0] - points[i][0]) + abs(points[j][1] - points[i][1])
