        if num == k:
            continue
        if num < k:
            operations += 1
        else:
            operations += abs(k - num)
    return operations

def kthSmallestCoin(coins, k):
    coins.sort()
    coins.sort(reverse=True)

    def coin_sum(coins):
        total = 0
        for coin in coins:
            total += coin
        return total

    return coin_sum(coins) + k

def minimumSum(nums, andValues):
    n = len(nums)
    m = len(andValues)
    dp = [[float('inf')] * (1 << m) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(1, 1 << m):
            for k in range(1, m):
                if (j & (1 << k)) == 0:
                    dp[i][j] = min(dp[i][j], dp[i - 1][j] + nums[i - 1])
                else:
                    dp[i][j] = min(dp[i][j], dp[i - 1][j] + nums[i - 1] & nums[i - 1])

    if dp[n][1 << m] == float('inf'):
        return -1
    else:
        return dp[n][1 << m]

from typing import List, Tuple

def mark_and_sum(nums: List[int], queries: List[Tuple[int, int]]) -> List[int]:
    n = len(nums)
    answer = [0] * m

    for index_i, k_i in queries:
        if index_i >= n:
            break

        marked = False
        marked_elements = []

        for i in range(n):
            if not marked:
                if i < k_i:
                    marked_elements.append(nums[i])
                else:
                    marked_elements.sort()
                    marked_elements.pop()
                    marked_elements.append(nums[i])
                marked = True

        answer[index_i] = sum(marked_elements)

    return answer

def replace_question_marks(s: str) -> str:
    s = list(s)
    for i in range(len(s)):
        if s[i] == '?':
            for c in 'abcdefghijklmnopqrstuvwxyz':
                s[i] = c
    return ''.join(s)

def sumOfPower(nums, k):
    MOD = 10**9 + 7
    n = len(nums)
    power = 0

    # Generate all subsequences
    for i in range(1, 1 << n):
        sum_val = 0
        for j in range(n):
            if i & (1 << j):
                sum_val += nums[j]
        if sum_val == k:
            power += 1

    return power % MOD

def minLevelsToWin(possible):
    n = len(possible)
    dp = [[-1 for _ in range(n+1)] for _ in range(n+1)]

    def dfs(i, j):
        if dp[i][j] != -1:
            return dp[i][j]

        if i == n:
            return 0

        if j == n:
            return 1

        if possible[i] == 0:
            dp[i][j] = dfs(i+1, j) + dfs(i+1, j-1)
        else:
            dp[i][j] = dfs(i+1, j) + dfs(i+1, j-1)

        return dp[i][j]

    return dfs(0, 0)

def minimum_possible_value(n, x):
    nums = [x] * n
    for i in range(1, n):
        nums[i] = nums[i - 1] + 1
    return nums[n - 1]

def median_of_uniqueness(nums):
    distinct_count = len(set(nums))
    n = len(nums)
    uniqueness_array = sorted(set(nums))
    uniqueness_array.sort()
    if n % 2 == 1:
        return uniqueness_array[n // 2]
    else:
        return (uniqueness_array[n // 2 - 1] + uniqueness_array[n // 2]) / 2

